      storeRoas_why: "أعلى من نظيره في مركز الحقيقة دائماً، والفرق بينهما هو مبيعاتك التي لم يجلبها إعلان. اتّساع الفرق خبرٌ جيّد: متجرك يبيع بنفسه.",
      storeRoi_what: "كم ربحت فعلاً من كلّ وحدة أنفقتَها على الإعلان، بعد كلّ تكلفة.",
      storeRoi_how: "(الربح قبل الإعلان − الإنفاق الإعلانيّ) ÷ الإنفاق الإعلانيّ. والربح هنا مقروءٌ من تكاليفك الحقيقية بنداً بنداً - بضاعة وشحن ورسوم ومرتجعات - لا مقدَّراً بنسبة هامش واحدة.",
